// Screen and interaction layout reconstructed from the public, authenticated UI.
data.edition ||= 'N23';

function editionSwitch(){return `<div class="edition-switch" role="group" aria-label="Edition"><button data-parity="edition" data-value="N23" class="${data.edition==='N23'?'selected':''}">N23</button><button data-parity="edition" data-value="N26" class="${data.edition==='N26'?'selected':''}">N26</button></div>`}
function homeTabs(active){return `<div class="tabs home-tabs"><button data-parity="home" data-value="gangs" class="${active==='gangs'?'active':''}">Gangs</button><button data-parity="home" data-value="campaigns" class="${active==='campaigns'?'active':''}">Campaigns</button></div>`}
function matchGangCard(g){return `<article class="card home-list-card"><button class="favorite ${g.favorite?'on':''}" data-parity="favorite-gang" data-id="${g.id}" aria-label="${g.favorite?'Remove favourite':'Add favourite'}">${g.favorite?'★':'☆'}</button><button class="home-card-main" data-open-gang="${g.id}"><h3>${esc(g.name)}</h3><p>${esc(g.faction)} · ${esc(g.edition)}</p><span>Rating ${fmt(rating(g))} &nbsp; Wealth ${fmt((g.credits||0)+rating(g))} &nbsp; ${g.fighters.length} Fighters</span></button></article>`}
function matchCampaignCard(c){return `<article class="card home-list-card"><button class="favorite ${c.favorite?'on':''}" data-parity="favorite-campaign" data-id="${c.id}" aria-label="${c.favorite?'Remove favourite':'Add favourite'}">${c.favorite?'★':'☆'}</button><button class="home-card-main" data-open-campaign="${c.id}"><h3>${esc(c.name)}</h3><p>${esc(c.campaignType||'Core Campaign')} · ${esc(c.edition)}</p><span>${c.members.length} Gangs & Players</span></button></article>`}
dashboard=function(){let tab=data.homeTab||'gangs',items=tab==='gangs'?data.gangs:data.campaigns;items=items.filter(x=>x.edition===data.edition).sort((a,b)=>(b.favorite?1:0)-(a.favorite?1:0));if(tab==='gangs'&&window.MMGangOrder)items=window.MMGangOrder.sort(items);return `<section class="home-welcome card"><h1>언더하이브 코리아</h1><p>네크로문다의 갱, 파이터와 캠페인을 한곳에서 관리하세요.</p><div class="actions"><button class="btn primary" data-action="new-gang">Create Gang</button><button class="btn" data-action="new-campaign">Create Campaign</button></div></section>${homeTabs(tab)}<section class="card home-section"><div class="section-heading"><h2>${tab==='gangs'?'Gangs':'Campaigns'}</h2><div class="home-section-actions">${tab==='gangs'&&items.length>1?'<button type="button" class="btn" data-gang-order-open><span data-i18n-ko="순서 변경" data-i18n-en="Change order">Change order</span></button>':''}${editionSwitch()}</div></div>${items.length?`<div class="home-list">${items.map(tab==='gangs'?matchGangCard:matchCampaignCard).join('')}</div>`:`<p class="muted empty-line">No ${tab} created yet.</p>`}</section>`};
gangsPage=function(){data.homeTab='gangs';return dashboard()};
campaignsPage=function(){data.homeTab='campaigns';return dashboard()};

function gangResourceSummary(g){return `<div class="match-stats"><div><small>Rating</small><strong>${fmt(rating(g))}</strong></div><div><small>Wealth</small><strong>${fmt(rating(g)+n(g.credits))}</strong></div><div><small>Credits</small><strong>${fmt(g.credits)}</strong></div><div><small>Reputation</small><strong>${fmt(g.reputation)}</strong></div></div>`}
function gangTop(g){return `<section class="card entity-card"><div class="entity-head"><div class="entity-title"><span class="entity-avatar">⚙</span><h1>${esc(g.name)}</h1></div></div><div class="entity-actions main-actions"><button class="btn small" data-parity="view-mode">Page View ▾</button><button class="btn small" data-parity="gang-resources">Resources</button><button class="btn small" data-action="edit-current-gang">Edit</button></div><div class="entity-tools"><button data-ext="copy-gang" title="Copy Gang" aria-label="Copy Gang">▣</button><button data-parity="gang-additions" title="Gang additions" aria-label="Gang additions">☷</button><button data-parity="capture" title="Capture" aria-label="Capture">▣</button><button data-parity="share" title="Share" aria-label="Share">♧</button><button data-ext="print-gang" title="Print" aria-label="Print">▤</button></div><p class="entity-meta">Owner: <strong>Local player</strong></p><p class="entity-meta">Type: <strong>${esc(g.faction)}</strong></p><div class="entity-facts"><span>Rating: <strong>${fmt(rating(g))}</strong></span><span>Reputation: <strong>${fmt(g.reputation)}</strong></span><span>Credits: <strong>${fmt(g.credits)}</strong></span><span>Trade Points: <strong>${fmt(g.tradePoints||0)}</strong></span><span>Wealth: <strong>${fmt(rating(g)+n(g.credits))}</strong></span><span>Gang Size: <strong>${g.fighters.length}</strong></span></div><div class="entity-main-buttons"><button class="btn" data-action="new-fighter">Add Fighter</button><div><button class="btn" data-ext="new-vehicle">Add Vehicle</button><button class="btn" data-parity="gang-additions">Gang Additions</button></div></div></section>`}
function gangMainTab(g){return `<div class="stack"><section class="card"><div class="section-heading"><h2>Fighters</h2><button class="btn primary" data-action="new-fighter">Add Fighter</button></div>${g.fighters.length?`<div class="fighter-grid ${data.gangListView?'list-view':''}">${g.fighters.map(f=>`<button class="fighter-card" data-parity="open-fighter" data-id="${f.id}"><div><h3>${esc(f.name)}</h3><p>${esc(f.type)} · ${esc(f.status)}</p></div><strong>${fmt(f.cost)}<small> Credits</small></strong><div class="fighter-stats">${Object.entries(f.stats).map(([k,v])=>`<span><b>${esc(k)}</b>${esc(v)}</span>`).join('')}<span><b>XP</b>${fmt(f.xp)}</span></div></button>`).join('')}</div>`:'<p class="muted">No fighters yet.</p>'}</section>${g.edition==='N26'?vehiclesTab(g):''}<section class="card"><div class="section-heading"><h2>Additional Details</h2><button class="btn small" data-parity="gang-additions">Gang Additions</button></div><div class="mini-list"><div class="mini-row"><span>Alignment</span><strong>${esc(g.alignment)}</strong></div><div class="mini-row"><span>Fighters</span><strong>${g.fighters.length}</strong></div><div class="mini-row"><span>Gang Rating</span><strong>${fmt(rating(g))}</strong></div></div></section></div>`}
function gangBattles(g){let memberships=data.campaigns.filter(c=>c.members.some(m=>m.gangId===g.id));return `<div class="stack"><section class="card"><div class="section-heading"><h2>Gang Tactics</h2><button class="btn small" data-ext="new-tactic">Add</button></div>${g.tactics?.length?g.tactics.map(t=>`<div class="mini-row"><span>${esc(t.name)}</span><button class="btn small danger" data-ext="delete-tactic" data-id="${t.id}">Remove</button></div>`).join(''):'<p class="muted">No tactics cards.</p>'}</section><section class="card"><div class="section-heading"><h2>Battle Sessions</h2><button class="btn small" data-parity="new-gang-battle">New</button></div><div class="segment"><button data-parity="battle-filter" data-value="active" class="${data.gangBattleFilter!=='all'?'selected':''}">Active</button><button data-parity="battle-filter" data-value="all" class="${data.gangBattleFilter==='all'?'selected':''}">All</button></div>${memberships.flatMap(c=>(c.sessions||[]).filter(s=>data.gangBattleFilter==='all'||s.status==='Active').map(s=>`<button class="mini-row full-button" data-parity="open-gang-battle" data-id="${s.id}" data-campaign="${c.id}"><span>${esc(s.scenario)}</span><small>${esc(c.name)} · ${esc(s.status)}</small></button>`)).join('')||'<p class="muted">No battle sessions.</p>'}</section></div>`}
gangPage=function(){let g=gang();if(!g)return gangsPage();extras(g);let tabs=[['fighters','Gang','♟'],['stash','Stash','▣'],...(g.edition==='N23'?[['vehicles','Vehicles','▰']]:[]),['campaign-link','Campaign','⚑'],['gang-notes','Notes','▤'],['battles','Battles','⚔']];return `<div class="tabs icon-tabs">${tabs.map(([v,label,icon])=>`<button data-tab="${v}" class="${(data.tab||'fighters')===v?'active':''}" aria-label="${label}" title="${label}"><span class="tab-icon">${icon}</span><span class="tab-text">${label}</span></button>`).join('')}</div>${(data.tab||'fighters')==='fighters'?gangTop(g):''}${({fighters:()=>gangMainTab(g),stash:()=>stashTab(g),vehicles:()=>vehiclesTab(g),'campaign-link':()=>gangCampaignTab(g),'gang-notes':()=>gangNotesTab(g),battles:()=>gangBattles(g)})[data.tab||'fighters']?.()||gangMainTab(g)}`};

function campaignTop(c){return `<section class="card entity-card"><div class="entity-head"><h1>${esc(c.name)}</h1><button class="btn small" data-action="edit-campaign">Edit</button></div><div class="entity-tools"><button data-parity="campaign-summary" title="Summary" aria-label="Summary">☷</button><button data-parity="campaign-json" title="View Campaign Data" aria-label="View Campaign Data">⌘</button><button data-parity="capture" title="Capture" aria-label="Capture">▣</button><button data-parity="share" title="Share" aria-label="Share">♧</button></div><p class="entity-meta">Arbitrator: <strong>Local player</strong></p><p class="entity-meta">Type: <strong>${esc(c.campaignType||'Core Campaign')}</strong> &nbsp; Status: <strong>${esc(c.phase)}</strong></p><p class="entity-meta">Trading Post: <strong>General Trading Post</strong></p><div class="entity-facts"><span>Players: <strong>${c.members.length}</strong></span><span>Territories: <strong>${c.territories.length}</strong></span><span>Gangs: <strong>${c.members.length}</strong></span><span>Battles: <strong>${c.battles.length}</strong></span></div></section>`}
function campaignMain(c){return `<div class="stack"><section class="card"><div class="section-heading"><h2>Gangs &amp; Players ⓘ</h2></div><input class="field" data-parity-search="players" placeholder="Search players by their username" aria-label="Search players"><div class="table-wrap"><table><thead><tr><th>Gang</th><th>Type</th><th>Player</th><th>Rating</th></tr></thead><tbody>${c.members.map(m=>{let g=data.gangs.find(g=>g.id===m.gangId);return `<tr class="campaign-player-row"><td>${g?`<button class="btn small" data-open-gang="${g.id}">${esc(g.name)}</button>`:'-'}</td><td>${esc(g?.faction||'-')}</td><td>${esc(m.player)}</td><td>${fmt(rating(g))}</td></tr>`}).join('')||`<tr><td><button class="btn small" data-action="new-member">Add your gang</button></td><td>-</td><td>Local player</td><td>-</td></tr>`}</tbody></table></div><button class="btn small" data-action="new-member">Add your gang</button></section><section class="card"><h2>Captured Fighters</h2>${c.members.flatMap(m=>data.gangs.find(g=>g.id===m.gangId)?.fighters.filter(f=>f.status==='Captured')||[]).map(f=>`<div class="mini-row">${esc(f.name)}</div>`).join('')||'<p class="muted"><i>No fighters are currently held captive by gangs in this campaign.</i></p>'}</section>${campaignResourceSection(c)}</div>`}
function campaignBattleView(c){return `<div class="stack"><section class="card"><div class="section-heading"><h2>Battle Sessions</h2><button class="btn primary" data-session="new">New</button></div><div class="segment"><button data-parity="session-filter" data-value="active" class="${data.sessionFilter!=='all'?'selected':''}">Active</button><button data-parity="session-filter" data-value="all" class="${data.sessionFilter==='all'?'selected':''}">All</button></div>${(c.sessions||[]).filter(s=>data.sessionFilter==='all'||s.status==='Active').map(s=>`<button class="mini-row full-button" data-session="detail" data-id="${s.id}"><span>${esc(s.scenario)}</span><small>${esc(s.status)}</small></button>`).join('')||'<p class="muted">No battle sessions.</p>'}</section><section class="card"><div class="section-heading"><h2>Battles</h2><button class="btn small" data-action="new-battle">Add</button></div>${c.battles.map(b=>`<div class="mini-row battle-filterable" data-cycle="${esc(b.cycle||'')}" data-scenario="${esc(b.name)}" data-gang="${esc([b.attacker,b.defender].map(id=>data.gangs.find(g=>g.id===id)?.name||'').join(' '))}" data-winner="${esc(data.gangs.find(g=>g.id===b.winner)?.name||'')}"><span>${esc(b.name)}</span><button class="btn small danger" data-battle-remove="${b.id}">Remove</button></div>`).join('')||'<p class="muted">No battles recorded.</p>'}</section><section class="card"><h2>Filters</h2><div class="filter-grid"><input class="field" data-parity-filter="cycle" placeholder="All Cycles"><input class="field" data-parity-filter="scenario" placeholder="All Scenarios"><input class="field" data-parity-filter="gang" placeholder="All Gangs"><input class="field" data-parity-filter="winner" placeholder="All Winners"></div></section><section class="card"><div class="section-heading"><h2>Standings</h2><button class="btn small" data-parity="challenge-round">Challenge Round</button></div>${c.members.map(m=>{let g=data.gangs.find(x=>x.id===m.gangId);return `<div class="mini-row"><span>${esc(g?.name||'Unknown Gang')}</span><strong>${c.battles.filter(b=>b.winner===m.gangId).length} wins</strong></div>`}).join('')||'<p class="muted">No gangs added.</p>'}</section></div>`}
campaignPage=function(){let c=campaign();if(!c)return campaignsPage();campaignExtras(c);c.sessions??=[];let tabs=[['members','Campaign','⚑'],['battles','Battles','⚔'],['territories','Territories','▥'],['map','Map','⌖'],['triumphs','Triumphs','★'],['pack','Custom Pack','▤']];let active=data.campaignTab||'members';return `<div class="tabs icon-tabs">${tabs.map(([v,label,icon])=>`<button data-campaign-tab="${v}" class="${active===v?'active':''}" aria-label="${label}" title="${label}"><span class="tab-icon">${icon}</span><span class="tab-text">${label}</span></button>`).join('')}</div>${active==='members'?campaignTop(c):''}${({members:()=>campaignMain(c),territories:()=>territoriesTab(c),battles:()=>campaignBattleView(c),pack:()=>packTab(c),map:()=>mapTab(c),triumphs:()=>triumphsTab(c)})[active]?.()||campaignMain(c)}`};

const priorCatalogPage=catalogPage;
catalogPage=function(){ensureAssets();let sections=assetKinds.map(([kind,label])=>{let arr=data.customAssets[kind];return `<section class="card asset-section"><div class="section-heading"><h2>${({equipment:'Equipment',fighters:'Fighters',skills:'Skills & Skill Sets',gangTypes:'Gang Types',tradingPosts:'Trading Posts',collections:'Asset Collections'})[kind]}</h2><button class="btn small" data-parity="create-asset" data-value="${kind}">Create</button></div>${arr.map(a=>`<div class="mini-row"><span>${esc(a.name)}</span><div class="actions"><button class="btn small" data-parity="edit-asset" data-value="${kind}" data-id="${a.id}">Edit</button><button class="btn small danger" data-parity="delete-asset" data-value="${kind}" data-id="${a.id}">Delete</button></div></div>`).join('')||'<p class="muted">No custom assets.</p>'}</section>`}).join('');return `<section class="home-welcome card"><h1>언더하이브 코리아</h1><div class="actions"><button class="btn" data-action="new-gang">Create Gang</button><button class="btn" data-action="new-campaign">Create Campaign</button></div></section>${homeTabs('catalog')}<div class="section-heading catalog-heading"><h2><span data-i18n-en="Custom" data-i18n-ko="커스텀">Custom</span></h2>${editionSwitch()}</div><div class="stack">${sections}</div>`};

const priorEditGang=editGang;
editGang=function(g){if(g)return priorEditGang(g);let allFactions=[...new Set([...factions,...data.customAssets.gangTypes.map(x=>x.name)])];formModal('Create a New Gang',select('edition','Edition *',['N23','N26'],data.edition)+select('faction','Gang Type *',allFactions,allFactions[0])+field('subtype','Gang Subtypes','')+field('credits','Starting Credits',1000,'number','min="0"')+'<label>Gang Name *<input name="name" required placeholder="Enter gang name"></label>',v=>{let created={id:id(),name:v.name.trim(),faction:v.faction,edition:v.edition,subtype:v.subtype,alignment:'Law Abiding',credits:n(v.credits),reputation:0,meat:0,exploration:0,notes:'',stash:[],fighters:[],vehicles:[],tactics:[],logs:[]};data.gangs.push(created);data.selectedGang=created.id;data.view='gang';data.tab='fighters';log(created,'Gang created.');save()},'Create Gang')};
const priorEditCampaign=editCampaign;
editCampaign=function(c){if(c)return priorEditCampaign(c);let posts=data.customAssets.tradingPosts;let postFields=`<fieldset class="wide"><legend>Authorised Trading Posts</legend><label class="checkline"><input type="checkbox" name="post" value="general" checked>General Trading Post</label>${posts.map(p=>`<label class="checkline"><input type="checkbox" name="post" value="${p.id}">${esc(p.name)}</label>`).join('')}</fieldset>`;formModal('Create a New Campaign',select('edition','Edition *',['N23','N26'],data.edition)+select('campaignType','Campaign Type *',['Core Campaign','Dominion','Law and Misrule','Custom'],'Core Campaign')+postFields+'<label>Campaign Name *<input name="name" required placeholder="Enter campaign name"></label>',v=>{let posts=[...$('#modal-form').querySelectorAll('[name="post"]:checked')].map(x=>x.value);let created={id:id(),name:v.name.trim(),edition:v.edition,campaignType:v.campaignType,tradingPosts:posts,phase:'Active',description:'',members:[],territories:[],battles:[],sessions:[],resources:[],triumphs:[],notes:''};data.campaigns.push(created);data.selectedCampaign=created.id;data.view='campaign';data.campaignTab='members';save()},'Create Campaign')};

document.addEventListener('click',e=>{let t=e.target.closest('[data-parity]');if(!t||t.matches('select'))return;e.stopImmediatePropagation();let d=t.dataset,g=gang(),c=campaign();switch(d.parity){case 'open-fighter':data.selectedFighter=d.id;data.view='fighter';save();break;case 'back-gang':data.view='gang';save();break;case 'select-fighter':data.selectedFighter=t.value;save();break;case 'fighter-status':{let f=g.fighters.find(x=>x.id===data.selectedFighter);if(d.value){showModal('Change Fighter Status',`<p>Set ${esc(f.name)} to ${esc(d.value)}?</p>`,'Confirm',()=>{f.status=d.value;log(g,`${f.name}: ${d.value}`);save()});}else formModal('Change Fighter Status',select('status','Status',['Active','In Recovery','Captured','Retired','Dead','Enslaved','Starved'],f.status),v=>{f.status=v.status;save()});break}case 'fighter-note':{let f=g.fighters.find(x=>x.id===data.selectedFighter);formModal('Fighter Notes',textarea('notes','Notes',f.notes||''),v=>{f.notes=v.notes;save()});break}case 'fighter-backstory':{let f=g.fighters.find(x=>x.id===data.selectedFighter);formModal('Fighter Backstory',textarea('backstory','Backstory',f.backstory||''),v=>{f.backstory=v.backstory;save()});break}case 'delete-fighter-page':{let f=g.fighters.find(x=>x.id===data.selectedFighter);confirmDelete('Delete Fighter',`Delete ${esc(f.name)}?`,()=>{g.fighters=g.fighters.filter(x=>x.id!==f.id);data.view='gang';save()});break}case 'home':data.view=d.value==='catalog'?'catalog':'dashboard';data.homeTab=d.value==='campaigns'?'campaigns':'gangs';save();break;case 'edition':data.edition=d.value;save();break;case 'favorite-gang':{let item=data.gangs.find(x=>x.id===d.id);item.favorite=!item.favorite;save();break}case 'favorite-campaign':{let item=data.campaigns.find(x=>x.id===d.id);item.favorite=!item.favorite;save();break}case 'dice':closeModal();diceRoll();break;case 'post-cycle':closeModal();postCycle();break;case 'gang-resources':resourceDeltaForm(g);break;case 'gang-additions':showModal('Gang Additions',`<div class="mini-list"><button class="btn" data-parity="goto-gang" data-value="resources">Resources</button><button class="btn" data-parity="goto-gang" data-value="logs">History</button><button class="btn" data-tab="gang-notes">Notes</button><button class="btn" data-tab="battles">Tactics Cards</button><button class="btn" data-parity="dice">Dice Roller</button><button class="btn" data-parity="post-cycle">Post Cycle</button><button class="btn danger" data-action="delete-gang">Delete Gang</button></div>`,'Close',()=>true);break;case 'goto-gang':closeModal();data.tab=d.value;save();break;case 'battle-filter':data.gangBattleFilter=d.value;save();break;case 'session-filter':data.sessionFilter=d.value;save();break;case 'new-gang-battle':{let membership=data.campaigns.find(x=>x.members.some(m=>m.gangId===g.id));if(!membership){showModal('Battle Sessions','<p>Add this gang to a campaign to create a battle session.</p>','Close',()=>true);break}data.selectedCampaign=membership.id;data.view='campaign';data.campaignTab='battles';save();sessionForm();break}case 'open-gang-battle':data.selectedCampaign=d.campaign;data.view='campaign';data.campaignTab='battles';save();sessionDetail(campaign().sessions.find(s=>s.id===d.id));break;case 'create-asset':data.assetTab=d.value;editAsset();break;case 'edit-asset':data.assetTab=d.value;editAsset(data.customAssets[d.value].find(a=>a.id===d.id));break;case 'delete-asset':data.assetTab=d.value;confirmDelete('Delete Asset','Delete this custom asset?',()=>{data.customAssets[d.value]=data.customAssets[d.value].filter(a=>a.id!==d.id);save()});break;case 'view-mode':showModal('View Mode','<div class="mini-list"><button class="btn" data-parity="view-list">List View</button><button class="btn" data-parity="view-page">Page View</button></div>','Close',()=>true);break;case 'view-list':closeModal();data.gangListView=true;save();break;case 'view-page':closeModal();data.gangListView=false;save();break;case 'campaign-summary':showModal('Campaign Summary',campaignTop(c),'Close',()=>true);break;case 'campaign-json':downloadCampaign('json');break;case 'capture':window.print();break;case 'share':showModal('Share Your Data','<p>Download your data and import it on another device.</p><button class="btn" data-action="export">Download JSON</button>','Close',()=>true);break;case 'challenge-new':closeModal();sessionForm();break;case 'challenge-round':openChallengeRound(c);break}},true);

document.addEventListener('click',e=>{let t=e.target.closest('[data-resource],[data-tab],[data-action]');if(t?.closest('.modal-bg')&&document.querySelectorAll('.modal-bg').length===1)closeModal()},true);

render();
function currentFighter(){return gang()?.fighters?.find(f=>f.id===data.selectedFighter)}
function fighterPage(){let g=gang(),f=currentFighter();if(!g||!f){data.view='gang';return gangPage()}fighterExtra(f);let num=(x)=>fmt(x||0);return `<section class="card fighter-page"><div class="fighter-picker"><button class="btn small" data-parity="back-gang">← ${esc(g.name)}</button><select aria-label="Select fighter" data-parity="select-fighter">${g.fighters.map(x=>`<option value="${x.id}" ${x.id===f.id?'selected':''}>${esc(x.name)} - ${esc(x.type)} (${esc(window.MMVerifiedRules?.xpDisplay?.(x,g)||num(x.xp))} XP)</option>`).join('')}</select></div><div class="fighter-banner"><div><h1>${esc(f.name)}</h1><p>${esc(f.type)}${f.status!=='Active'?' · '+esc(f.status):''}</p></div><strong>${num(f.cost)}<small>Credits</small></strong></div><div class="fighter-page-actions"><span>☠ OOA: ${num(f.kills)}</span><button class="btn" data-play="add-xp" data-id="${f.id}">Add XP</button><button class="btn" data-edit-fighter="${f.id}">Edit</button></div><div class="fighter-detail-stats">${Object.entries(f.stats).map(([k,v])=>`<span><b>${esc(k)}</b>${esc(v)}</span>`).join('')}<span><b>XP</b>${num(f.xp)}</span></div><section><div class="section-heading"><h2>Equipment</h2><div class="actions"><button class="btn small" data-play="new-loadout" data-id="${f.id}">Loadouts</button><button class="btn small" data-add-equipment="${f.id}">Add</button></div></div><div class="table-wrap fp-equipment-table-wrap"><table class="fp-equipment-table" role="table" aria-label="Fighter equipment" data-i18n-ko-aria-label="파이터 장비"><colgroup><col><col class="fp-equipment-cost-column"><col class="fp-equipment-actions-column"></colgroup><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Name</th><th scope="col" role="columnheader">Cost</th><th scope="col" role="columnheader">Action</th></tr></thead><tbody role="rowgroup">${f.equipment.map(x=>`<tr role="row" data-fighter-equipment-row="${esc(x.id)}"><td class="fp-equipment-name" role="cell">${esc(x.name)}</td><td class="fp-equipment-cost" role="cell"><span class="fp-equipment-price">${num(x.cost)}<small data-i18n-ko="크레딧">cr</small></span></td><td class="fp-equipment-operations" role="cell"><div class="fp-equipment-row-actions"><button class="btn small fp-equipment-action" data-to-stash="${f.id}:${x.id}" aria-label="Move to stash" data-i18n-ko-aria-label="보관함으로 이동" title="Move to stash" data-i18n-ko-title="보관함으로 이동"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M4 7h16v13H4zM3 3h18v4H3zM9 11h6"/></svg><span class="fp-equipment-action-label" data-i18n-ko="보관함">Stash</span></button><button class="btn small fp-equipment-action" data-deep="sell-equipment" data-fighter="${f.id}" data-id="${x.id}" aria-label="Sell" data-i18n-ko-aria-label="장비 판매" title="Sell" data-i18n-ko-title="장비 판매"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M12 2v20M17 6H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg><span class="fp-equipment-action-label" data-i18n-ko="판매">Sell</span></button></div></td></tr>`).join('')||'<tr role="row" class="fp-equipment-empty-row"><td role="cell" colspan="3">No equipment.</td></tr>'}</tbody></table></div></section><section><div class="section-heading"><h2>Skills</h2><button class="btn small" data-add-skill="${f.id}">Add</button></div><div class="table-wrap fp-skills-table-wrap"><table class="fp-skills-table"><thead><tr><th scope="col">Name</th><th scope="col">Source</th><th scope="col">Action</th></tr></thead><tbody>${f.skills.map((x,i)=>`<tr><td>${esc(x)}</td><td>Fighter</td><td><button class="btn small danger" data-ext="remove-skill" data-id="${f.id}" data-sub="${i}">Delete</button></td></tr>`).join('')||'<tr><td colspan="3">No skills.</td></tr>'}</tbody></table></div></section><section><div class="section-heading"><h2>Advancements</h2><button class="btn small" data-play="add-advancement" data-id="${f.id}">Add</button></div>${f.advancements.map(a=>`<div class="mini-row"><span>${esc(a.name)} · ${num(a.xpCost)} XP</span><button class="btn small danger" data-play="remove-advancement" data-id="${f.id}" data-sub="${a.id}">Delete</button></div>`).join('')||'<p class="muted">No advancements.</p>'}</section><section><div class="section-heading"><h2>Lasting Injuries</h2><button class="btn small" data-play="add-injury" data-id="${f.id}">Add</button></div>${f.injuries.map(a=>`<div class="mini-row"><span>${esc(a.name)}</span><button class="btn small" data-play="heal-injury" data-id="${f.id}" data-sub="${a.id}">Heal</button></div>`).join('')||'<p class="muted">No lasting injuries.</p>'}</section><section><div class="section-heading"><h2>Fighter Notes</h2><button class="btn small" data-parity="fighter-note">Edit</button></div><p>${esc(f.notes||'No notes.')}</p></section><section><div class="section-heading"><h2>Fighter Backstory</h2><button class="btn small" data-parity="fighter-backstory">Edit</button></div><p>${esc(f.backstory||'No backstory.')}</p></section><div class="fighter-status-actions"><button class="btn" data-parity="fighter-status">Change Status</button><button class="btn" data-ext="copy-fighter" data-id="${f.id}">Copy Fighter</button><button class="btn" data-parity="fighter-status" data-value="Dead">Kill Fighter</button><button class="btn" data-parity="fighter-status" data-value="Retired">Retire Fighter</button><button class="btn" data-parity="fighter-status" data-value="In Recovery">Send to Recovery</button><button class="btn" data-parity="fighter-status" data-value="Captured">Capture Fighter</button><button class="btn danger" data-parity="delete-fighter-page">Delete Fighter</button></div></section>`}
const beforeFighterPageRender=render;render=function(){beforeFighterPageRender();let crumb=document.querySelector('.crumb');if(data.view==='fighter'){document.querySelector('.content').innerHTML=fighterPage();crumb.innerHTML=`<span>⌂</span> / ${esc(gang()?.name||'Gang')} / <strong>${esc(currentFighter()?.name||'Fighter')}</strong>`}else if(data.view==='gang')crumb.innerHTML=`<span>⌂</span> / <strong>${esc(gang()?.name||'Gang')}</strong>`;else if(data.view==='campaign')crumb.innerHTML=`<span>⌂</span> / Campaigns / <strong>${esc(campaign()?.name||'Campaign')}</strong>`;else if(data.view==='dashboard'||data.view==='catalog'||data.view==='gangs'||data.view==='campaigns')crumb.innerHTML='<span>⌂</span>'};
document.addEventListener('change',e=>{if(e.target.matches('[data-parity="select-fighter"]')){data.selectedFighter=e.target.value;save()}});
render();

document.addEventListener('input',e=>{if(e.target.matches('[data-parity-search="players"]')){let q=e.target.value.toLowerCase();document.querySelectorAll('.campaign-player-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}if(e.target.matches('[data-parity-filter]')){let fields=[...document.querySelectorAll('[data-parity-filter]')];document.querySelectorAll('.battle-filterable').forEach(row=>{row.hidden=fields.some(field=>field.value&&!row.dataset[field.dataset.parityFilter]?.toLowerCase().includes(field.value.toLowerCase()))})}});
